userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="btnPlay" class="active">⏸ Pause flow</button>
<label>Diffusion timestep t
  <input type="range" id="sldT" min="0" max="1000" step="50" value="500">
  <span id="tVal" style="font-size:10px;color:#555">t = 500</span>
</label>
<div style="display:flex;flex-direction:column;gap:2px">
  <span style="font-weight:bold">Highlight block type</span>
  <button id="btAll" class="active">All blocks</button>
  <button id="btRes">Res. block</button>
  <button id="btAttn">Res. block + self-attention</button>
</div>
<div style="display:flex;flex-direction:column;gap:2px;border-top:1px solid #ddd;padding-top:4px">
  <span style="font-weight:bold">Demo steps</span>
  <button id="step0">1 · Full architecture</button>
  <button id="step1">2 · Where is self-attention?</button>
  <button id="step2">3 · Effect of timestep</button>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── ELEMENT SPEC ─────────────────────────────────────────────────────────
// input/output image plane → BoxGeometry(3.2, 3.2, 0.15), noise CanvasTexture
// feature-map volume       → BoxGeometry(s, s, depth) terracotta material array
//                            (front #b96a43, side #8a4a2e, top #d98d63)
// skip connection          → THREE.Line polyline salmon #d98d63 + cone arrowhead
// flow arrow               → ArrowHelper, dark #3a3a3a (res) / light #9ab0bc (+attn)
// time-embedding trunk     → THREE.Line #5f7a8a at y=-2.6
// branch arrow             → ArrowHelper #5f7a8a, trunk → block base
// t node                   → TorusGeometry ring at (-13,-2.6) + label
// pulse                    → SphereGeometry(0.09) #ffcf40 travelling block to block
// ──────────────────────────────────────────────────────────────────────────

const TERRA = 0xb96a43, SIDE = 0x8a4a2e, TOP = 0xd98d63, SALMON = 0xd98d63;
const GREYBLUE = 0x5f7a8a, DARKA = 0x3a3a3a, LIGHTA = 0x9ab0bc;

// volume table: x, spatial size s, channels → depth, self-attention?, label
const LV = [
  { x: -11.0, s: 3.00, ch: 128, attn: false, label: '256×256×128' },
  { x: -9.35, s: 2.40, ch: 128, attn: false, label: '128×128×128' },
  { x: -7.70, s: 1.80, ch: 256, attn: false, label: '64×64×256' },
  { x: -6.05, s: 1.30, ch: 256, attn: false, label: '32×32×256' },
  { x: -4.40, s: 0.85, ch: 512, attn: true, label: '16×16×512' },
  { x: -2.90, s: 0.55, ch: 512, attn: true, label: '8×8×512' },   // bottleneck
  { x: -1.40, s: 0.55, ch: 512, attn: true },
  { x: 0.10, s: 0.85, ch: 512, attn: true },
  { x: 1.60, s: 1.30, ch: 256, attn: false },
  { x: 3.25, s: 1.80, ch: 256, attn: false },
  { x: 4.90, s: 2.40, ch: 128, attn: false },
  { x: 6.55, s: 3.00, ch: 128, attn: false },
];
const CH_DEPTH = { 128: 0.5, 256: 0.7, 512: 1.0 };
const IN_X = -12.6, OUT_X = 8.6, TRUNK_Y = -2.6;

/* ── noise texture ─────────────────────────────────────────────────────── */
function makeNoiseTexture(alpha) {
  const N = 96, cv = document.createElement('canvas');
  cv.width = cv.height = N;
  const g = cv.getContext('2d');
  const img = g.createImageData(N, N);
  for (let i = 0; i < N * N; i++) {
    // base grey-pink photo-ish tone, increasingly replaced by pure RGB noise
    const br = 150 + Math.sin(i * 0.13) * 30 + Math.cos(i * 0.031) * 25;
    const nr = Math.random() * 255, ng = Math.random() * 255, nb = Math.random() * 255;
    img.data[i * 4] = br * (1 - alpha) + nr * alpha;
    img.data[i * 4 + 1] = (br - 12) * (1 - alpha) + ng * alpha;
    img.data[i * 4 + 2] = (br - 20) * (1 - alpha) + nb * alpha;
    img.data[i * 4 + 3] = 255;
  }
  g.putImageData(img, 0, 0);
  const tx = new THREE.CanvasTexture(cv);
  tx.colorSpace = THREE.SRGBColorSpace;
  return tx;
}

/* ── input / output image planes ───────────────────────────────────────── */
let inputTex = makeNoiseTexture(0.5);
const outTex = makeNoiseTexture(0.18);
function makeImagePlane(x, tex) {
  const m = new THREE.Mesh(
    new THREE.BoxGeometry(3.2, 3.2, 0.15),
    new THREE.MeshBasicMaterial({ map: tex })
  );
  m.position.set(x, 0.3, 0);
  scene.add(m);
  return m;
}
const inPlane = makeImagePlane(IN_X, inputTex);
const outPlane = makeImagePlane(OUT_X, outTex);
registerInteractive(inPlane, {
  title: 'Noisy input 256×256×3',
  body: 'The noisy image xₜ enters the U-Net here. The timestep slider controls how much Gaussian noise has been added (noise α = t/1000).',
  tooltip: 'Noisy input image'
});
registerInteractive(outPlane, {
  title: 'Predicted noise / output',
  body: 'The decoder mirrors the encoder back to full 256×256 resolution; the network outputs the noise prediction used for the denoising update.',
  tooltip: 'Output image'
});

/* ── feature-map slabs ─────────────────────────────────────────────────── */
const slabs = [];
function slabMats() {
  return [SIDE, SIDE, TOP, SIDE, TERRA, SIDE].map(c =>
    new THREE.MeshBasicMaterial({ color: c, transparent: true }));
}
LV.forEach((L, i) => {
  const mats = slabMats();
  const mesh = new THREE.Mesh(
    new THREE.BoxGeometry(L.s, L.s, CH_DEPTH[L.ch]), mats);
  mesh.position.set(L.x, L.s / 2 - 1.9, 0);
  scene.add(mesh);
  slabs.push({ mesh, mats, L, i });
  registerInteractive(mesh, {
    title: (L.attn ? 'Res. block + self-attention' : 'Res. block') +
      (L.label ? ' · ' + L.label : ''),
    body: L.attn
      ? 'Self-attention is used only at small spatial resolutions (16×16, 8×8), where attention over spatial positions is affordable.'
      : 'A residual convolutional block. The time embedding is injected into every block (grey-blue arrows below).',
    tooltip: L.label || '8×8×512'
  });
});

/* ── flow arrows between successive stages ─────────────────────────────── */
const stages = [{ x: IN_X, s: 3.2, attn: false }, ...LV, { x: OUT_X, s: 3.2, attn: false }];
const flowArrows = [];
for (let i = 0; i < stages.length - 1; i++) {
  const a = stages[i], b = stages[i + 1];
  const y0 = -1.7;
  const dir = new THREE.Vector3(1, 0, 0);
  const len = Math.max(0.35, (b.x - a.x) - a.s / 2 - b.s / 2 - 0.15);
  const col = b.attn ? LIGHTA : DARKA;
  const ar = new THREE.ArrowHelper(dir,
    new THREE.Vector3(a.x + a.s / 2 + 0.06, y0, 0), len, col, 0.16, 0.09);
  scene.add(ar);
  flowArrows.push({ ar, col, attn: b.attn });
}

/* ── skip connections (Concatenate) ────────────────────────────────────── */
const skipLines = [];
const SKIP_H = [2.6, 2.05, 1.5, 1.05, 0.72, 0.42];
for (let k = 0; k < 6; k++) {
  const e = slabs[k], dc = slabs[11 - k];
  const y = SKIP_H[k];
  const ey = e.mesh.position.y + e.L.s / 2, dy = dc.mesh.position.y + dc.L.s / 2;
  const pts = [
    new THREE.Vector3(e.x, ey, 0),
    new THREE.Vector3(e.x, y, 0),
    new THREE.Vector3(dc.x, y, 0),
    new THREE.Vector3(dc.x, dy + 0.12, 0),
  ];
  const mat = new THREE.LineBasicMaterial({ color: SALMON });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
  scene.add(line);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.24, 10),
    new THREE.MeshBasicMaterial({ color: SALMON }));
  cone.position.set(dc.x, dy + 0.05, 0);
  cone.rotation.x = Math.PI; // point down into decoder block
  scene.add(cone);
  skipLines.push({ mat, coneMat: cone.material, base: new THREE.Color(SALMON), k });
}

/* ── time-embedding trunk + branch arrows ──────────────────────────────── */
const trunkPts = [new THREE.Vector3(-13.4, TRUNK_Y, 0), new THREE.Vector3(OUT_X + 0.2, TRUNK_Y, 0)];
scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(trunkPts),
  new THREE.LineBasicMaterial({ color: GREYBLUE })));

const ring = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.035, 10, 40),
  new THREE.MeshBasicMaterial({ color: GREYBLUE }));
ring.position.set(-13.4, TRUNK_Y, 0);
scene.add(ring);

const branchArrows = [];
stages.forEach(st => {
  const ar = new THREE.ArrowHelper(new THREE.Vector3(0.25, 1, 0).normalize(),
    new THREE.Vector3(st.x - 0.1, TRUNK_Y + 0.05, 0),
    (st.s / 2 - 1.9) - TRUNK_Y - 0.05 + 1.9 - st.s / 2 + st.s / 2 - 1.9 - TRUNK_Y - 0.05 > 0 ?
      ((st.s / 2 - 1.9) - TRUNK_Y - 0.05) : 0.5, GREYBLUE, 0.14, 0.08);
  // recompute simply: from trunk up to block base
  ar.position.set(st.x - 0.15, TRUNK_Y + 0.05, 0);
  ar.setDirection(new THREE.Vector3(0.2, 1, 0).normalize());
  ar.setLength(Math.max(0.4, (st.s / 2 - 1.9) - TRUNK_Y - 0.15), 0.14, 0.08);
  scene.add(ar);
  branchArrows.push(ar);
});

/* ── pulse (forward pass animation) ────────────────────────────────────── */
const pulse = new THREE.Mesh(new THREE.SphereGeometry(0.11, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0xffcf40 }));
scene.add(pulse);
const flash = new Array(6).fill(0);
let pulseT = 0, playing = true;

/* ── camera, then labels ───────────────────────────────────────────────── */
setCameraView({
  projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5,
  axisScreenAngles: null, rollDeg: 0, heightFraction: 0.7
});

const LBL = { color: '#8a4a2e', fontSize: '13px' };
function resLabel(txt, x, y, off) {
  addLabel('<i>' + txt + '</i>', new THREE.Vector3(x, y, 0),
    { ...LBL, offset: off || [0, 0] });
}
resLabel('256×256×3', IN_X + 0.4, 2.4, [0, -14]);
resLabel('256×256×128', LV[0].x + 0.4, 2.15, [0, -14]);
resLabel('128×128×128', LV[1].x + 0.3, 1.55, [0, -12]);
resLabel('64×64×256', LV[2].x + 0.3, 0.95, [0, -12]);
resLabel('32×32×256', LV[3].x + 0.2, 0.55, [0, -10]);
resLabel('16×16×512', LV[4].x + 0.15, 0.3, [0, -10]);
resLabel('8×8×512', LV[5].x + 0.1, 0.12, [0, -10]);
[0, 1, 2, 3].forEach(k => {
  addLabel('Concatenate',
    new THREE.Vector3((slabs[k].x + slabs[11 - k].x) / 2, SKIP_H[k] + 0.02, 0),
    { color: '#8a4a2e', fontSize: '15px', offset: [0, -12] });
});
addLabel('t', new THREE.Vector3(-13.4, TRUNK_Y, 0), { fontSize: '14px', bold: true, color: '#3a5560' });
addLabel('time embedding', new THREE.Vector3(-11.6, TRUNK_Y - 0.28, 0),
  { color: '#3a5560', fontSize: '13px' });
addLabel(
  '<span style="color:#3a3a3a">➜</span> Res. block<br>' +
  '<span style="color:#9ab0bc">➜</span> Res. block +<br>&nbsp;&nbsp;&nbsp;self-attention',
  new THREE.Vector3(-12.4, 3.5, 0),
  { background: '#ffffff', fontSize: '13px', offset: [30, 0] });

/* ── interaction state ─────────────────────────────────────────────────── */
let tVal = 500, blockType = 'All blocks';
const sldT = document.getElementById('sldT');
const tValEl = document.getElementById('tVal');

function applyTimestep(v) {
  tVal = v;
  tValEl.textContent = 't = ' + v;
  const alpha = v / 1000;
  const old = inputTex;
  inputTex = makeNoiseTexture(alpha);
  inPlane.material.map = inputTex;
  inPlane.material.needsUpdate = true;
  old.dispose();
  // branch arrows brighten sequentially as t increases
  const lit = Math.round(alpha * branchArrows.length);
  branchArrows.forEach((ar, i) => {
    const on = i < lit;
    ar.setColor(on ? 0x2e86c1 : 0xb9c6cd);
  });
}
sldT.addEventListener('input', () => applyTimestep(+sldT.value));

function applyBlockType(mode) {
  blockType = mode;
  [['btAll', 'All blocks'], ['btRes', 'Res. block'], ['btAttn', 'Res. block + self-attention']]
    .forEach(([id, m]) =>
      document.getElementById(id).classList.toggle('active', m === mode));
  slabs.forEach(({ mats, L }) => {
    const match = mode === 'All blocks' ||
      (mode === 'Res. block') === !L.attn;
    mats.forEach(m => { m.opacity = match ? 1 : 0.25; });
  });
  flowArrows.forEach(({ ar, col, attn }) => {
    const match = mode === 'All blocks' ||
      (mode === 'Res. block') === !attn;
    ar.setColor(match ? col : 0xdcdcdc);
  });
}
document.getElementById('btAll').onclick = () => applyBlockType('All blocks');
document.getElementById('btRes').onclick = () => applyBlockType('Res. block');
document.getElementById('btAttn').onclick = () => applyBlockType('Res. block + self-attention');

const btnPlay = document.getElementById('btnPlay');
btnPlay.onclick = () => {
  playing = !playing;
  btnPlay.textContent = playing ? '⏸ Pause flow' : '▶ Encoder–decoder pass';
  btnPlay.classList.toggle('active', playing);
};

/* ── demo steps ────────────────────────────────────────────────────────── */
function goToStep(n) {
  if (n === 0) {
    sldT.value = 500; applyTimestep(500); applyBlockType('All blocks');
    showPopup('Full architecture',
      'A noisy 256×256×3 image is downsampled through residual blocks to an 8×8×512 bottleneck, then upsampled back, with skip connections concatenating encoder features at each scale.');
  } else if (n === 1) {
    applyBlockType('Res. block + self-attention');
    showPopup('Where is self-attention?',
      'Attention blocks appear only at the small 16×16 and 8×8 resolutions, where the quadratic cost of attention over spatial positions is manageable.');
  } else {
    applyBlockType('All blocks');
    sldT.value = 1000; applyTimestep(1000);
    showPopup('Effect of timestep',
      'As t grows the input image becomes noisier and more time-embedding injections light up — the same network is conditioned on the noise level at every scale.');
  }
}
document.getElementById('step0').onclick = () => goToStep(0);
document.getElementById('step1').onclick = () => goToStep(1);
document.getElementById('step2').onclick = () => goToStep(2);

applyTimestep(500);

/* ── animation loop (pulse + skip flashes) ─────────────────────────────── */
const path = stages.map(st => new THREE.Vector3(st.x, st.s / 2 - 1.9 + 0.05, 0));
const SEG_T = 0.6;
let lastT = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;
  if (playing) {
    pulseT += dt / SEG_T;
    const total = path.length - 1;
    if (pulseT >= total) { pulseT = 0; }
    const i = Math.floor(pulseT), f = pulseT - i;
    pulse.position.lerpVectors(path[i], path[Math.min(i + 1, total)], f);
    pulse.position.y += 0.18;
    // crossing into a decoder stage (index >= 7 in stages) flashes its skip line
    if (f < dt / SEG_T && i >= 7) {
      const decIdx = i - 7;              // 0..5 ↔ slabs 6..11
      if (decIdx >= 0 && decIdx < 6) flash[5 - decIdx] = 1;
    }
  }
  for (let k = 0; k < 6; k++) {
    if (flash[k] > 0.01) {
      flash[k] *= Math.pow(0.02, dt);
      const c = skipLines[k].base.clone().lerp(new THREE.Color(0xff4400), flash[k]);
      skipLines[k].mat.color.copy(c);
      skipLines[k].coneMat.color.copy(c);
    }
  }
  pulse.visible = playing;
}
requestAnimationFrame(tick);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
