/* ── noise texture ─────────────────────────────────────────────────────── */
function makeNoiseTexture(alpha) {
  const N = 96, cv = document.createElement('canvas');
  cv.width = cv.height = N;
  const g = cv.getContext('2d');
  const img = g.createImageData(N, N);
  for (let i = 0; i < N * N; i++) {
    // base grey-pink photo-ish tone, increasingly replaced by pure RGB noise
    const br = 150 + Math.sin(i * 0.13) * 30 + Math.cos(i * 0.031) * 25;
    const nr = Math.random() * 255, ng = Math.random() * 255, nb = Math.random() * 255;
    img.data[i * 4] = br * (1 - alpha) + nr * alpha;
    img.data[i * 4 + 1] = (br - 12) * (1 - alpha) + ng * alpha;
    img.data[i * 4 + 2] = (br - 20) * (1 - alpha) + nb * alpha;
    img.data[i * 4 + 3] = 255;
  }
  g.putImageData(img, 0, 0);
  const tx = new THREE.CanvasTexture(cv);
  tx.colorSpace = THREE.SRGBColorSpace;
  return tx;
}

/* ── input / output image planes ───────────────────────────────────────── */
let inputTex = makeNoiseTexture(0.5);
const outTex = makeNoiseTexture(0.18);
function makeImagePlane(x, tex) {
